@extends('layouts.storefront')
@section('title','My Orders | MEETA')
@push('styles')
<style>
.orders-page{padding-top:50px;padding-bottom:40px;min-height:65vh}.orders-head{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:28px}.orders-head h1{font:600 42px 'Playfair Display',serif;margin:0 0 7px}.orders-head p{margin:0;color:var(--muted)}.filters{display:flex;gap:10px;flex-wrap:wrap}.filters select{border:1px solid var(--line);background:#fff;padding:11px 35px 11px 13px;color:var(--ink)}.orders-list{display:flex;flex-direction:column;gap:18px}.order-card{background:#fff;border:1px solid var(--line);transition:.18s ease}.order-card:hover{box-shadow:0 12px 34px rgba(63,38,23,.08);transform:translateY(-1px)}.order-card-head{background:#fbf3ee;border-bottom:1px solid var(--line);padding:15px 20px;display:grid;grid-template-columns:1.1fr .8fr .8fr auto;gap:24px;align-items:center}.eyebrow{font-size:10px;letter-spacing:.8px;text-transform:uppercase;color:var(--muted);font-weight:600;margin-bottom:3px}.head-value{font-size:13px;font-weight:600}.order-number{color:var(--brown)}.card-body{padding:20px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:24px;align-items:center}.preview-items{display:flex;gap:14px;min-width:0}.preview{display:flex;gap:11px;align-items:center;min-width:0;max-width:290px}.preview-pic{width:68px;height:68px;flex:0 0 68px;background:#f2e5dd;overflow:hidden;display:grid;place-items:center;color:var(--brown);font:600 22px 'Playfair Display',serif}.preview-pic img{width:100%;height:100%;object-fit:cover}.preview-name{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.preview-meta{font-size:12px;color:var(--muted);margin-top:4px}.more-items{width:68px;height:68px;display:grid;place-items:center;background:#f8efea;color:var(--muted);font-weight:600}.card-actions{text-align:right}.status{display:inline-flex;gap:7px;align-items:center;padding:7px 12px;border-radius:30px;text-transform:capitalize;font-size:12px;font-weight:600;background:#f1e7e1}.status:before{content:'';width:7px;height:7px;border-radius:50%;background:currentColor}.status-delivered{background:#e5f2e8;color:#397248}.status-shipped{background:#e2f1f3;color:#28707a}.status-cancelled,.status-returned{background:#f8e1df;color:#a23e39}.status-processing{background:#e8edf7;color:#3e5f98}.view-link{display:inline-block;margin-top:13px;color:var(--brown);font-weight:600;font-size:13px;border-bottom:1px solid currentColor}.empty,.state{background:#fff;border:1px solid var(--line);text-align:center;padding:80px 20px}.empty h2{font:600 27px 'Playfair Display',serif}.empty p,.state{color:var(--muted)}.pagination{display:flex;justify-content:center;align-items:center;gap:12px;margin-top:25px}.pagination button{padding:10px 15px;border:1px solid var(--line);background:#fff;cursor:pointer}.pagination button:disabled{opacity:.4}
@media(max-width:800px){.orders-head{align-items:flex-start;flex-direction:column}.order-card-head{grid-template-columns:1fr 1fr}.card-body{grid-template-columns:1fr}.card-actions{text-align:left}.preview-items{overflow:hidden}}@media(max-width:520px){.orders-page{padding-top:32px}.orders-head h1{font-size:34px}.filters{width:100%}.filters select{flex:1}.order-card-head>div:nth-child(3){display:none}.card-body{padding:16px}.preview:nth-child(n+2){display:none}.preview-pic{width:60px;height:60px;flex-basis:60px}}
</style>
