@section('content')
<main class="orders-page wrap"><div class="orders-head"><div><h1>My Orders</h1><p>Track every piece, from the artisan's hands to your home.</p></div><div class="filters"><select id="statusFilter"><option value="">All orders</option><option value="confirmed">Confirmed</option><option value="processing">Processing</option><option value="shipped">Shipped</option><option value="delivered">Delivered</option><option value="cancelled">Cancelled</option></select><select id="yearFilter"></select></div></div><div id="orders" class="orders-list"><div class="state">Finding your orders…</div></div><div class="pagination" id="pagination" hidden><button id="prevPage">← Previous</button><span id="pageLabel"></span><button id="nextPage">Next →</button></div></main>
@endsection
@push('scripts')
<script>
if(protectPage()){
 let page=1,lastPage=1;const orderUrl=@json(url('/orders'));const money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Number(v||0));const date=v=>new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',year:'numeric'}).format(new Date(v));const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const label=v=>String(v||'').replaceAll('_',' ');
 const year=document.getElementById('yearFilter'),now=new Date().getFullYear();year.innerHTML='<option value="">All years</option>'+Array.from({length:Math.max(1,now-2019)},(_,i)=>now-i).map(y=>`<option>${y}</option>`).join('');
 function itemPreview(i){return `<div class="preview"><div class="preview-pic">${i.image?`<img src="${esc(i.image)}" alt="">`:esc((i.product_name||'M')[0])}</div><div style="min-width:0"><div class="preview-name">${esc(i.product_name)}</div><div class="preview-meta">${esc(i.variant_name||'Standard')} · Qty ${i.quantity}</div></div></div>`}
 function render(orders){const box=document.getElementById('orders');if(!orders.length){box.innerHTML='<div class="empty"><h2>No matching orders</h2><p>Your orders will appear here after checkout.</p><a class="btn primary" href="/categories">Explore crafts</a></div>';return}box.innerHTML=orders.map(o=>`<article class="order-card"><div class="order-card-head"><div><div class="eyebrow">Order number</div><div class="head-value order-number">${esc(o.order_number)}</div></div><div><div class="eyebrow">Placed on</div><div class="head-value">${date(o.placed_at)}</div></div><div><div class="eyebrow">Total</div><div class="head-value">${money(o.total_amount)}</div></div><div><span class="status status-${o.order_status}">${label(o.order_status)}</span></div></div><div class="card-body"><div class="preview-items">${o.preview_items.map(itemPreview).join('')}${o.total_items>o.preview_items.reduce((s,i)=>s+i.quantity,0)?`<div class="more-items">+${o.total_items-o.preview_items.reduce((s,i)=>s+i.quantity,0)}</div>`:''}</div><div class="card-actions"><div>${o.total_items} item${o.total_items===1?'':'s'} · ${o.total_packages} package${o.total_packages===1?'':'s'}</div><a class="view-link" href="${orderUrl}/${o.id}">View order details →</a></div></div></article>`).join('')}
 async function load(){document.getElementById('orders').innerHTML='<div class="state">Finding your orders…</div>';const q=new URLSearchParams({page,per_page:8}),status=document.getElementById('statusFilter').value,y=document.getElementById('yearFilter').value;if(status)q.set('status',status);if(y)q.set('year',y);try{const {data}=await api('/api/customer/orders?'+q);render(data.orders||[]);lastPage=data.pagination.last_page||1;const pager=document.getElementById('pagination');pager.hidden=data.pagination.total<=data.pagination.per_page;document.getElementById('pageLabel').textContent=`Page ${page} of ${lastPage}`;document.getElementById('prevPage').disabled=page<=1;document.getElementById('nextPage').disabled=page>=lastPage}catch(e){document.getElementById('orders').innerHTML=`<div class="state">${esc(e.message)}<br><button class="btn" onclick="load()">Try again</button></div>`}}
 document.getElementById('statusFilter').onchange=document.getElementById('yearFilter').onchange=()=>{page=1;load()};document.getElementById('prevPage').onclick=()=>{if(page>1){page--;load();scrollTo(0,0)}};document.getElementById('nextPage').onclick=()=>{if(page<lastPage){page++;load();scrollTo(0,0)}};load();
}
</script>
@endpush
